const items = $input.all();
const markdown = items[0].json.stdout || '';
const buildings = [];

// 從 webhook body 讀取設定參數（含預設值）
const body = $node['Webhook'].json.body || {};
const skipCompleted = body.skip_completed !== undefined ? body.skip_completed : true;
const startCategory = body.start_category || '法定古蹟';
const startNumber = body.start_number || '00001';
const priorityBuildings = body.priority_buildings || [];

const categoryOrder = ['法定古蹟', '市區', '新界'];
const startCatIdx = categoryOrder.indexOf(startCategory);
if (startCatIdx === -1) startCatIdx = 0;

const sectionMap = {'法定古蹟':'法定古蹟','市區':'市區','新界':'新界'};
const sections = markdown.split(/^(?=### )/m);
const allParsed = [];

for (const section of sections) {
  const headerMatch = section.match(/^### (.+)/);
  if (!headerMatch) continue;
  const category = sectionMap[headerMatch[1].trim()];
  if (!category) continue;
  const lines = section.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed.startsWith('|')) continue;
    if (trimmed.includes('---')) continue;
    if (trimmed.includes('編號')) continue;
    const rawCells = trimmed.split('|');
    rawCells.shift(); rawCells.pop();
    if (rawCells.length < 10) continue;
    const buildingId = rawCells[0].trim();
    if (!/^\d+$/.test(buildingId)) continue;
    const status = rawCells[8].trim();
    allParsed.push({
      building_id: buildingId,
      category: category,
      chinese_name: rawCells[2].trim(),
      english_name: rawCells[3].trim(),
      chinese_address: rawCells[4].trim(),
      english_address: rawCells[5].trim(),
      status: status,
      is_completed: status.includes('已完成')
    });
  }
}

// 1) 優先處理 priority_buildings 清單
const prioritySet = new Set(priorityBuildings.map(String));
const priorityItems = allParsed.filter(b => prioritySet.has(String(b.building_id)));

// 2) 依分類順序 + 起始編號篩選
const filteredItems = allParsed.filter(b => {
  const catIdx = categoryOrder.indexOf(b.category);
  if (catIdx < startCatIdx) return false;
  if (catIdx === startCatIdx && parseInt(b.building_id) < parseInt(startNumber)) return false;
  if (skipCompleted && b.is_completed) return false;
  if (prioritySet.has(String(b.building_id))) return false;
  return true;
});

const finalBuildings = [...priorityItems, ...filteredItems];
for (const b of finalBuildings) {
  buildings.push({json: {
    building_id: b.building_id, category: b.category,
    chinese_name: b.chinese_name, english_name: b.english_name,
    chinese_address: b.chinese_address, english_address: b.english_address,
    is_completed: b.is_completed
  }});
}
if (buildings.length > 0) {
  buildings[0].json._filter_summary = {
    skip_completed: skipCompleted, start_category: startCategory,
    start_number: startNumber, priority_count: priorityItems.length,
    total_filtered: buildings.length
  };
}
return buildings;

const items = $input.all();
const stdout = items[0].json.stdout || '';
const exitCode = items[0].json.exitCode;
const stderr = items[0].json.stderr || '';
const buildingId = $('設定建築物變數').item.json.building_id;
let result = {building_id: buildingId, exit_code: exitCode, raw_stdout: stdout, status: 'unknown', error: null, logs: []};
if (exitCode !== 0) {
  result.status = 'failed'; result.error = 'CrewAI exited with code ' + exitCode;
  result.logs.push({type: 'error', message: stderr || 'Unknown error'});
  return [{json: result}];
}
try {
  const lines = stdout.trim().split('\n');
  for (const line of lines) {
    const t = line.trim(); if (!t) continue;
    try { const p = JSON.parse(t); result.logs.push(p); if (p.status) result.status = p.status; if (p.verdict) result.status = p.verdict === 'passed' ? 'passed' : 'failed'; } catch(e) { result.logs.push({type:'text',message:t}); }
  }
} catch(e) { result.error = e.message; }
return [{json: result}];

const items = $input.all();
const stdout = items[0].json.stdout || '';
const exitCode = items[0].json.exitCode;
const buildingId = $('設定建築物變數').item.json.building_id;
let result = {building_id: buildingId, status: 'failed', verdict: 'unknown', issues: [], confidence_score: 0};
if (exitCode !== 0 || !stdout.trim()) { result.issues.push({description:'intermediate_research.json empty or missing'}); return [{json: result}]; }
try {
  const r = JSON.parse(stdout);
  if (r.status) result.status = r.status;
  if (r.verdict) { result.verdict = r.verdict; result.status = r.verdict === 'passed' ? 'passed' : 'failed'; }
  if (r.credibility_task) { const ct = r.credibility_task; if (ct.verdict) { result.verdict = ct.verdict; result.status = ct.verdict === 'passed' ? 'passed' : 'failed'; } if (ct.issues) result.issues = ct.issues; if (ct.confidence_score !== undefined) result.confidence_score = ct.confidence_score; }
  if (r.research_task && r.research_task.sources) result.sources_count = r.research_task.sources.length;
  if (r.retry_count !== undefined) result.retry_count = r.retry_count;
} catch(e) { result.status = 'failed'; result.issues.push({description:'Parse error: '+e.message}); }
return [{json: result}];
